function useBrandGradientId(prefix: string) {
  const raw = useId();
  return `${prefix}-${raw.replace(/[^a-zA-Z0-9_-]/g, "")}`;
}

/** 深底圆角应用图标：启动壳、登录面板、关于窗、Web/手机端共用。 */
export function ChengAppIcon({
  className,
  animated = false,
  ...props
}: SVGProps<SVGSVGElement> & { animated?: boolean }) {
  const gradientId = useBrandGradientId("cheng-app-icon");

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="100"
      height="100"
      viewBox="0 0 100 100"
      className={cn("shrink-0", className)}
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {animated ? (
        <animate
          attributeName="opacity"
          begin="3s"
          dur="1.8s"
          repeatCount="indefinite"
          values="1;0.4;1"
        />
      ) : null}
      <defs>
        <linearGradient
          id={gradientId}
          x1="10"
          y1="6"
          x2="104"
          y2="110"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" stopColor="#F3EEFF" />
          <stop offset=".45" stopColor="#B59AFF" />
          <stop offset="1" stopColor="#6E4BF2" />
        </linearGradient>
      </defs>
      <rect width="100" height="100" rx="22" fill="#0B0910" />
      <g transform="translate(11.5 6) scale(.78)">
        <path fill={`url(#${gradientId})`} fillRule="evenodd" d={MARK_PATH} />
        <path fill="none" stroke={`url(#${gradientId})`} strokeWidth="6.5" d={MARK_RING_PATH} />
        <circle cx="60" cy="60" r="5.5" fill={`url(#${gradientId})`} />
      </g>
    </svg>
  );
}

/** 官方字标：C 保留品牌渐变，字母用 currentColor 以适配深浅主题。 */
export function ChengWordmark({ className, ...props }: SVGProps<SVGSVGElement>) {
  const gradientId = useBrandGradientId("cheng-wordmark");

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="214"
      height="88"
      viewBox="0 0 213.9 88"
      className={cn("shrink-0", className)}
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      <defs>
        <linearGradient
          id={gradientId}
          x1="0"
          y1="-60"
          x2="50"
          y2="2"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0" style={{ stopColor: "var(--cheng-wordmark-gradient-start, #f3eeff)" }} />
          <stop offset=".45" stopColor="#B59AFF" />
          <stop offset="1" stopColor="#6E4BF2" />
        </linearGradient>
      </defs>
      <g transform="translate(19.13 62.63)">
        <path fill={`url(#${gradientId})`} fillRule="evenodd" d={WORDMARK_GLYPH_PATH} />
        <path fill="currentColor" d={WORDMARK_LETTERS_PATH} />
      </g>
    </svg>
  );
}
